CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE TABLE users (id uuid PRIMARY KEY, external_subject text UNIQUE NOT NULL, display_name text NOT NULL, email text, status text NOT NULL CHECK(status IN ('active','disabled')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE courses (id uuid PRIMARY KEY, code text UNIQUE, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE course_instances (id uuid PRIMARY KEY, course_id uuid NOT NULL REFERENCES courses(id) ON DELETE RESTRICT, term text NOT NULL, teacher_name text, timezone text NOT NULL DEFAULT 'Asia/Shanghai', status text NOT NULL CHECK(status IN ('active','archived')), created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE enrollments (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), course_instance_id uuid NOT NULL REFERENCES course_instances(id), role text NOT NULL CHECK(role IN ('maintainer','student')), status text NOT NULL CHECK(status IN ('active','left')), joined_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,course_instance_id));
CREATE TABLE course_meetings (id uuid PRIMARY KEY, course_instance_id uuid NOT NULL REFERENCES course_instances(id), weekday smallint NOT NULL CHECK(weekday BETWEEN 1 AND 7), start_time time NOT NULL, end_time time NOT NULL CHECK(start_time < end_time), location text, valid_from date, valid_to date, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(valid_from IS NULL OR valid_to IS NULL OR valid_from <= valid_to));
CREATE TABLE source_items (id uuid PRIMARY KEY, course_instance_id uuid NOT NULL REFERENCES course_instances(id), submitted_by uuid NOT NULL REFERENCES users(id), source_type text NOT NULL CHECK(source_type IN ('text','file')), raw_text text, checksum text, status text NOT NULL CHECK(status IN ('queued','processing','review_ready','failed','completed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ingestion_jobs (id uuid PRIMARY KEY, source_item_id uuid NOT NULL UNIQUE REFERENCES source_items(id), stage text NOT NULL, status text NOT NULL, attempts integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 3, queue_task_id text, error_code text, error_message text, started_at timestamptz, finished_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assignment_candidates (id uuid PRIMARY KEY, source_item_id uuid NOT NULL REFERENCES source_items(id), ordinal smallint NOT NULL, title text NOT NULL, description text NOT NULL DEFAULT '', official_due_at timestamptz, raw_due_expression text, submission_method text, evidence jsonb NOT NULL DEFAULT '[]', field_confidence jsonb NOT NULL DEFAULT '{}', uncertain_fields jsonb NOT NULL DEFAULT '[]', review_status text NOT NULL CHECK(review_status IN ('pending','accepted','rejected')), reviewed_by uuid REFERENCES users(id), reviewed_at timestamptz, review_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_item_id,ordinal));
CREATE TABLE assignments (id uuid PRIMARY KEY, course_instance_id uuid NOT NULL REFERENCES course_instances(id) ON DELETE RESTRICT, title text NOT NULL, description text NOT NULL DEFAULT '', official_due_at timestamptz, submission_method text, status text NOT NULL CHECK(status IN ('published','cancelled')), source_candidate_id uuid UNIQUE REFERENCES assignment_candidates(id), created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assignment_user_states (id uuid PRIMARY KEY, assignment_id uuid NOT NULL REFERENCES assignments(id), user_id uuid NOT NULL REFERENCES users(id), personal_due_at timestamptz, completion_status text NOT NULL CHECK(completion_status IN ('todo','completed')), completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(assignment_id,user_id), CHECK((completion_status='completed' AND completed_at IS NOT NULL) OR (completion_status='todo' AND completed_at IS NULL)));
CREATE INDEX idx_enrollments_user_status_course ON enrollments(user_id,status,course_instance_id); CREATE INDEX idx_meetings_course_weekday ON course_meetings(course_instance_id,weekday); CREATE INDEX idx_assignments_course_due ON assignments(course_instance_id,official_due_at,id); CREATE INDEX idx_states_user_personal_due ON assignment_user_states(user_id,personal_due_at,assignment_id); CREATE INDEX idx_candidates_source_review ON assignment_candidates(source_item_id,review_status,ordinal);
